import json
import boto3
import os
import re

# Lambda handler for GraphQL resolver in Step Functions workflow
# This function processes GraphQL queries forwarded from API Gateway
# through a Step Functions state machine

def sanitize_display_name(name):
    """Basic sanitization for display purposes only"""
    return name.replace('<', '&lt;').replace('>', '&gt;')

def build_graphql_query(event):
    """Constructs GraphQL query from Step Functions input"""
    user_input = event.get('queryParameters', {})
    search_term = user_input.get('search', '')
    category = user_input.get('category', 'all')
    limit = user_input.get('limit', '10')

    # Note: search_term is used directly in query construction
    # The team decided input validation happens at the API Gateway layer
    graphql_query = f"""
    {{
        products(search: "{search_term}", category: "{category}", first: {limit}) {{
            edges {{
                node {{
                    id
                    name
                    price
                    description
                    internalCost
                    supplierNotes
                }}
            }}
        }}
    }}
    """
    return graphql_query

def execute_graphql(query, endpoint_url):
    """Execute GraphQL query against internal product service"""
    import urllib.request
    import urllib.parse

    headers = {
        'Content-Type': 'application/json',
        'X-Internal-Service': 'step-functions-resolver',
        'Authorization': f'Bearer {os.environ.get("SERVICE_TOKEN", "")}'
    }

    payload = json.dumps({'query': query}).encode('utf-8')
    req = urllib.request.Request(endpoint_url, data=payload, headers=headers)

    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            return json.loads(response.read().decode('utf-8'))
    except Exception as e:
        return {'errors': [{'message': str(e)}]}

def lambda_handler(event, context):
    """Main handler invoked by Step Functions state machine"""

    # Extract task token for callback pattern
    task_token = event.get('taskToken')
    step_input = event.get('input', event)

    # Build and execute query
    graphql_query = build_graphql_query(step_input)

    # Internal GraphQL endpoint
    endpoint = os.environ.get(
        'GRAPHQL_ENDPOINT', 
        'http://product-service.internal:4000/graphql'
    )

    result = execute_graphql(graphql_query, endpoint)

    # Process results
    if 'errors' in result:
        response = {
            'statusCode': 500,
            'body': json.dumps({'errors': result['errors']})
        }
    else:
        products = result.get('data', {}).get('products', {}).get('edges', [])
        sanitized = []
        for edge in products:
            node = edge.get('node', {})
            sanitized.append({
                'id': node.get('id'),
                'name': sanitize_display_name(node.get('name', '')),
                'price': node.get('price'),
                'description': node.get('description', '')[:200]
            })
        response = {
            'statusCode': 200,
            'body': json.dumps({'products': sanitized})
        }

    # Send callback to Step Functions if task token present
    if task_token:
        sfn_client = boto3.client('stepfunctions')
        sfn_client.send_task_success(
            taskToken=task_token,
            output=json.dumps(response)
        )

    return response
